SELECT brp.toolDate, brp.orderDate, brp.billDate, brp.billPayId, brp.billNum, brp.patientId, brp.patientName, brp.mobile, brp.gender, brp.regDentistId, brp.regDentistName, brp.orderAmount, brp.privilegeAmount, brp.actualAmount, brp.receivedAmount, brp.stillOweAmount, brp.remainingOweAmount, brp.payeeUserId, brp.payeeUserName FROM ( SELECT DATE_FORMAT( bbp.payee_date, '%Y-%m-%d' ) AS toolDate, DATE_FORMAT( bb.order_date, '%Y-%m-%d' ) AS orderDate, DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) AS billDate, bbp.bill_pay_id AS billPayId, bb.bill_num AS billNum, tp.patient_id AS patientId, tp.`name` AS patientName, tp.pinyin_name AS pinyinName, tp.mobile AS mobile, tp.gender AS gender, tp.registered_dentist_id AS regDentistId, tp.regDentistName AS regDentistName, bb.order_amount AS orderAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bbp.org_id as orgId, bbp.received_amount AS receivedAmount, bbp.still_owe_amount AS stillOweAmount, bb.debt_amount AS remainingOweAmount, bbp.payee_user_id AS payeeUserId, be.employee_name AS payeeUserName FROM base_bill_pay bbp LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.treatment_id, bp.patient_id, bp.`name`, bp.pinyin_name, bp.mobile, bp.gender, btp.registered_dentist_id, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id ) tp ON bbp.treatment_id = tp.treatment_id ) brp
and brp.orgId = #{query.orgId}
and brp.billNum like concat('%', #{query.billNum}, '%')
and concat(IFNULL(brp.patientName, ''),IFNULL(brp.pinyinName, ''), IFNULL(brp.mobile, '')) like concat('%', #{query.keyWord}, '%')
and brp.toolDate >= #{query.tollStartDate}
and brp.toolDate <= #{query.tollEndDate}
and brp.billDate >= #{query.billStartDate}
and brp.billDate <= #{query.billEndDate}
and brp.regDentistId in
#{item}
ORDER BY brp.toolDate DESC

SELECT
IFNULL(SUM( bbp.totalReceivedDebtAmount ), 0) AS totalReceivedDebtAmount,
IFNULL(SUM( bbp.totalReceivedAmount ), 0) AS totalReceivedAmount,
IFNULL(SUM( bbp.totalBillRefundAmount ), 0) AS totalBillRefundAmount,
IFNULL(SUM( bbp.totalClinicCollectionAmount ), 0) AS totalClinicCollectionAmount,
IFNULL(SUM( bbp.totalClinicCollectedAmount ), 0) AS totalClinicCollectedAmount
FROM
(
SELECT
bo.org_id,
IFNULL( bbp.totalReceivedDebtAmount, 0 ) AS totalReceivedDebtAmount,
IFNULL( bbp1.totalReceivedAmount, 0 ) AS totalReceivedAmount,
IFNULL( br.totalBillRefundAmount, 0 ) AS totalBillRefundAmount,
IFNULL( bbp2.totalClinicCollectionAmount, 0 ) AS totalClinicCollectionAmount,
IFNULL( bbp3.totalClinicCollectedAmount, 0 ) AS totalClinicCollectedAmount
FROM
base_organization bo
LEFT JOIN (
SELECT
bbp.org_id,
SUM( bbp.received_amount ) AS totalReceivedDebtAmount
FROM
(
SELECT
bbp.org_id,
bbp.received_amount,
bbp.payee_date,
bb.bill_date
FROM
base_bill_pay bbp
LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



) bbp
WHERE
bbp.payee_date != bbp.bill_date
GROUP BY
bbp.org_id
) bbp ON bo.org_id = bbp.org_id
LEFT JOIN (
SELECT
bbp.org_id,
SUM( bbp.received_amount ) AS totalReceivedAmount
FROM
base_bill_pay bbp



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



GROUP BY
bbp.org_id
) bbp1 ON bo.org_id = bbp1.org_id
LEFT JOIN (
SELECT
br.org_id,
SUM( br.refund_amount ) AS totalBillRefundAmount
FROM
base_refund br



            and DATE_FORMAT( br.refund_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( br.refund_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( br.refund_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( br.refund_date, '%Y') <= #{query.endDate}



GROUP BY
br.org_id
) br ON bo.org_id = br.org_id
LEFT JOIN (
SELECT
bbp.tollOrgId,
SUM( bbp.received_amount ) AS totalClinicCollectionAmount
FROM
(
SELECT
bbp.org_id AS tollOrgId,
bbp.received_amount,
bb.org_id AS billOrgId
FROM
base_bill_pay bbp
LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



) bbp
WHERE
bbp.tollOrgId != bbp.billOrgId
GROUP BY
bbp.tollOrgId
) bbp2 ON bo.org_id = bbp2.tollOrgId
LEFT JOIN (
SELECT
bbp.billOrgId,
SUM( bbp.received_amount ) AS totalClinicCollectedAmount
FROM
(
SELECT
bbp.org_id AS tollOrgId,
bbp.received_amount,
bb.org_id AS billOrgId
FROM
base_bill_pay bbp
LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id



            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m-%d') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y-%m') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y-%m') <= #{query.endDate}




            and DATE_FORMAT( bbp.payee_date, '%Y') >= #{query.startDate}


            and DATE_FORMAT( bbp.payee_date, '%Y') <= #{query.endDate}



) bbp
WHERE
bbp.tollOrgId != bbp.billOrgId
GROUP BY
bbp.billOrgId
) bbp3 ON bo.org_id = bbp3.billOrgId
) bbp


        and bbp.org_id in

            #{item}

SELECT
SUM( bbp.received_amount )
FROM
base_bill_pay bbp


        and bbp.org_id = #{query.orgId}


        AND DATE_FORMAT( bbp.payee_date, '%Y-%m' ) = #{query.queryDate}

    AND bbp.bill_id IN (
    SELECT
    bb.bill_id
    FROM
    base_bill bb

        and bb.bill_num IS NOT NULL
        AND bb.bill_date IS NOT NULL

            and bb.org_id = #{query.orgId}


            AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) = #{query.queryDate}


    )

SELECT billPayId, payeeDate, billId, billNum, billDate, patientId, patientName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT billPayId, DATE_FORMAT(payeeDate, '%Y-%m-%d') AS payeeDate, billId, billNum, DATE_FORMAT(billDate, '%Y-%m-%d') AS billDate, patientId, patientName, pinyin_name AS pinyinName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT bbp.org_id AS orgId, bbp.bill_pay_id AS billPayId, bbp.payee_date AS payeeDate, bbp.bill_id AS billId, bb.bill_num AS billNum, bb.bill_date AS billDate, btp.patientId, btp.patientName, btp.patientMobile, btp.pinyin_name, btp.regDentistId, btp.regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS totalReceivedAmount, bbp.received_amount AS receivedAmount, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.org_id, btp.treatment_id, btp.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.org_id, btp.treatment_id, btp.patient_id, bp.`name`, bp.mobile, bp.pinyin_name, btp.registered_dentist_id, be.employee_name ) btp ON bbp.treatment_id = btp.treatment_id ) bbp, ( SELECT bb.org_id, bb.bill_id, bb.bill_date FROM base_bill bb
AND bb.bill_date IS NOT NULL AND bb.bill_num IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) <= #{query.endDate}
GROUP BY bb.org_id, bb.bill_id, bb.bill_date ) bb
AND bbp.billId = bb.bill_id AND bbp.payeeDate = bb.bill_date AND bbp.orgId = bb.org_id
) bbp
AND concat(IFNULL(bbp.patientName, ''),IFNULL(bbp.pinyinName, ''), IFNULL(bbp.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND bbp.billNum LIKE concat('%', #{query.billNum}, '%')
AND bbp.payeeDate >= #{query.chargeStartDate}
AND bbp.payeeDate <= #{query.chargeEndDate}

SELECT billPayId, payeeDate, billId, billNum, billDate, patientId, patientName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT billPayId, DATE_FORMAT(payeeDate, '%Y-%m-%d') AS payeeDate, billId, billNum, DATE_FORMAT(billDate, '%Y-%m-%d') AS billDate, patientId, patientName, pinyin_name AS pinyinName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT bbp.org_id AS orgId, bbp.bill_pay_id AS billPayId, bbp.payee_date AS payeeDate, bbp.bill_id AS billId, bb.bill_num AS billNum, bb.bill_date AS billDate, btp.patientId, btp.patientName, btp.patientMobile, btp.pinyin_name, btp.regDentistId, btp.regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS totalReceivedAmount, bbp.received_amount AS receivedAmount, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.org_id, btp.treatment_id, btp.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.org_id, btp.treatment_id, btp.patient_id, bp.`name`, bp.mobile, bp.pinyin_name, btp.registered_dentist_id, be.employee_name ) btp ON bbp.treatment_id = btp.treatment_id ) bbp, ( SELECT bb.org_id, bb.bill_id, bb.bill_date FROM base_bill bb -- 门诊当前时间段内的账单 AND bb.bill_date IS NOT NULL AND bb.bill_num IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) <= #{query.endDate}
GROUP BY bb.org_id, bb.bill_id, bb.bill_date ) bb
AND bbp.orgId = bb.org_id AND bbp.payeeDate != bb.bill_date -- 收费时间跟账单时间不同则表示收欠费,并且收费日期在查询时间段内 AND bbp.billId = bb.bill_id
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y' ) <= #{query.endDate}
) bbp
AND concat(IFNULL(bbp.patientName, ''),IFNULL(bbp.pinyinName, ''), IFNULL(bbp.patientMobile, '')) like concat('%', #{query.patientKeyword}, '%')
AND bbp.billNum LIKE concat('%', #{query.billNum}, '%')
AND bbp.payeeDate >= #{query.chargeStartDate}
AND bbp.payeeDate <= #{query.chargeEndDate}

SELECT billPayId, payeeDate, billId, billNum, billDate, patientId, patientName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT billPayId, DATE_FORMAT(payeeDate, '%Y-%m-%d') AS payeeDate, billId, billNum, DATE_FORMAT(billDate, '%Y-%m-%d') AS billDate, patientId, patientName, pinyin_name AS pinyinName, patientMobile, regDentistId, regDentistName, originalAmount, privilegeAmount, actualAmount, totalReceivedAmount, receivedAmount, payeeId, payeeName FROM ( SELECT bbp.org_id AS orgId, bbp.bill_pay_id AS billPayId, bbp.payee_date AS payeeDate, bbp.bill_id AS billId, bb.bill_num AS billNum, bb.bill_date AS billDate, btp.patientId, btp.patientName, btp.patientMobile, btp.pinyin_name, btp.regDentistId, btp.regDentistName, bb.order_amount AS originalAmount, bb.privilege_amount AS privilegeAmount, bb.actual_amount AS actualAmount, bb.received_amount AS totalReceivedAmount, bbp.received_amount AS receivedAmount, bbp.payee_user_id AS payeeId, be.employee_name AS payeeName FROM base_bill_pay bbp LEFT JOIN base_bill bb ON bbp.bill_id = bb.bill_id LEFT JOIN base_employee be ON bbp.payee_user_id = be.user_id LEFT JOIN ( SELECT btp.org_id, btp.treatment_id, btp.patient_id AS patientId, bp.`name` AS patientName, bp.mobile AS patientMobile, bp.pinyin_name, btp.registered_dentist_id AS regDentistId, be.employee_name AS regDentistName FROM base_treatment_process btp LEFT JOIN base_patient bp ON btp.patient_id = bp.patient_id LEFT JOIN base_employee be ON btp.registered_dentist_id = be.user_id WHERE btp.treat_end_time IS NOT NULL GROUP BY btp.org_id, btp.treatment_id, btp.patient_id, bp.`name`, bp.mobile, bp.pinyin_name, btp.registered_dentist_id, be.employee_name ) btp ON bbp.treatment_id = btp.treatment_id ) bbp, ( SELECT bb.org_id, bb.bill_id, bb.bill_date FROM base_bill bb -- 账单日期小于查询开始时间或大于查询结束时间（大于查询结束时间的账单收费不会在查询时间范围内），表示非当月账单 AND bb.bill_date IS NOT NULL AND bb.bill_num IS NOT NULL
AND bb.org_id = #{query.orgId}
AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d' ) < #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y-%m' ) < #{query.startDate}
AND DATE_FORMAT( bb.bill_date, '%Y' ) < #{query.startDate}
GROUP BY bb.org_id, bb.bill_id, bb.bill_date ) bb
AND bbp.orgId = bb.org_id AND bbp.payeeDate != bb.bill_date -- 收费时间跟账单时间不同则表示收欠费,并且收费日期在查询时间段内 AND bbp.billId = bb.bill_id
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT( bbp.payeeDate, '%Y' ) <= #{query.endDate}
) bbp
AND concat(IFNULL(bbp.patientName, ''), IFNULL(bbp.pinyinName, ''), IFNULL(bbp.patientMobile, '')) LIKE concat('%', #{query.patientKeyword}, '%')
AND bbp.billNum LIKE concat('%', #{query.billNum}, '%')
AND bbp.payeeDate >= #{query.chargeStartDate}
AND bbp.payeeDate <= #{query.chargeEndDate}
